// 공통 전역 상태 함수와 상수를 최상단에 불러옵니다.
import { getState, setState } from '../state.js';
import { THEME } from '../constants.js';

export function initHeader() {
  /* -------------------------------------------------- */
  /* [가로채기] 화면이 그려지기 전에 다크모드부터 주입 */
  /* -------------------------------------------------- */
  const { theme } = getState();
  const isDarkTheme = theme === THEME.DARK;

  if (isDarkTheme) {
    document.body.classList.add('dark-mode');
  }

  /* -------------------------------------------------- */
  /* [파트 1] 다크모드 토글 전역 상태 관리                 */
  /* -------------------------------------------------- */
  const toggleBtn = document.querySelector('button[aria-label="다크 모드 전환"]');

  if (toggleBtn) {
    const moonSvg = toggleBtn.innerHTML;
    const sunSvg = `
      <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 16 16" fill="none">
        <path d="M7.9948 11.9922C9.05498 11.9922 10.0717 11.571 10.8214 10.8214C11.571 10.0717 11.9922 9.05498 11.9922 7.9948C11.9922 6.93462 11.571 5.91787 10.8214 5.16821C10.0717 4.41855 9.05498 3.9974 7.9948 3.9974C6.93462 3.9974 5.91787 4.41855 5.16821 5.16821C4.41855 5.91787 3.9974 6.93462 3.9974 7.9948C3.9974 9.05498 4.41855 10.0717 5.16821 10.8214C5.91787 11.571 6.93462 11.9922 7.9948 11.9922ZM7.9948 0C8.12732 0 8.25442 0.0526442 8.34812 0.146351C8.44183 0.240059 8.49448 0.367153 8.49448 0.499675V2.49837C8.49448 2.6309 8.44183 2.75799 8.34812 2.8517C8.25442 2.94541 8.12732 2.99805 7.9948 2.99805C7.86228 2.99805 7.73518 2.94541 7.64148 2.8517C7.54777 2.75799 7.49513 2.6309 7.49513 2.49837V0.499675C7.49513 0.367153 7.54777 0.240059 7.64148 0.146351C7.73518 0.0526442 7.86228 0 7.9948 0ZM7.9948 12.9916C8.12732 12.9916 8.25442 13.0442 8.34812 13.1379C8.44183 13.2316 8.49448 13.3587 8.49448 13.4912V15.4899C8.49448 15.6224 8.44183 15.7495 8.34812 15.8432C8.25442 15.937 8.12732 15.9896 7.9948 15.9896C7.86228 15.9896 7.73518 15.937 7.64148 15.8432C7.54777 15.7495 7.49513 15.6224 7.49513 15.4899V13.4912C7.49513 13.3587 7.54777 13.2316 7.64148 13.1379C7.73518 13.0442 7.86228 12.9916 7.9948 12.9916ZM15.9896 7.9948C15.9896 8.12732 15.937 8.25442 15.8432 8.34812C15.7495 8.44183 15.6224 8.49448 15.4899 8.49448H13.4912C13.3587 8.49448 13.2316 8.44183 13.1379 8.34812C13.0442 8.25442 12.9916 8.12732 12.9916 7.9948C12.9916 7.86228 13.0442 7.73518 13.1379 7.64148C13.2316 7.54777 13.3587 7.49513 13.4912 7.49513H15.4899C15.6224 7.49513 15.7495 7.54777 15.8432 7.64148C15.937 7.73518 15.9896 7.86228 15.9896 7.9948ZM2.99805 7.9948C2.99805 8.12732 2.94541 8.25442 2.8517 8.34812C2.75799 8.44183 2.6309 8.49448 2.49837 8.49448H0.499675C0.367153 8.49448 0.240059 8.44183 0.146351 8.34812C0.0526442 8.25442 0 7.9948 0 7.9948C0 7.86228 0.0526442 7.73518 0.146351 7.64148C0.240059 7.54777 0.367153 7.49513 0.499675 7.49513H2.49837C2.6309 7.49513 2.75799 7.54777 2.8517 7.64148C2.94541 7.73518 2.99805 7.86228 2.99805 7.9948ZM13.6481 2.34148C13.7418 2.43518 13.7944 2.56225 13.7944 2.69475C13.7944 2.82724 13.7418 2.95431 13.6481 3.04802L12.235 4.4621C12.1886 4.50849 12.1334 4.54528 12.0728 4.57036C12.0121 4.59544 11.9471 4.60833 11.8814 4.60828C11.7488 4.60819 11.6217 4.55542 11.528 4.4616C11.4816 4.41514 11.4448 4.36 11.4197 4.29933C11.3947 4.23865 11.3818 4.17363 11.3818 4.10797C11.3819 3.97538 11.4347 3.84825 11.5285 3.75456L12.9416 2.34148C13.0353 2.2478 13.1624 2.19518 13.2949 2.19518C13.4273 2.19518 13.5544 2.2478 13.6481 2.34148ZM4.4611 11.5285C4.55477 11.6222 4.6074 11.7493 4.6074 11.8818C4.6074 12.0143 4.55477 12.1413 4.4611 12.235L3.04802 13.6481C2.95378 13.7391 2.82756 13.7895 2.69655 13.7884C2.56553 13.7872 2.44021 13.7347 2.34756 13.642C2.25492 13.5494 2.20237 13.4241 2.20123 13.2931C2.20009 13.162 2.25046 13.0358 2.34148 12.9416L3.75456 11.5285C3.84826 11.4348 3.97533 11.3822 4.10783 11.3822C4.24032 11.3822 4.3674 11.4348 4.4611 11.5285ZM13.6481 13.6481C13.5544 13.7418 13.4273 13.7944 13.2949 13.7944C13.1624 13.7944 13.0353 13.7418 12.9416 13.6481L11.5285 12.235C11.4375 12.1408 11.3871 12.0146 11.3883 11.8836C11.3894 11.7526 11.4419 11.6272 11.5346 11.5346C11.6272 11.4419 11.7526 11.3894 11.8836 11.3883C12.0146 11.3871 12.1408 11.4375 12.235 11.5285L13.6481 12.9416C13.7418 13.0353 13.7944 13.1624 13.7944 13.2949C13.7944 13.4273 13.7418 13.5544 13.6481 13.6481ZM4.4611 4.4621C4.3674 4.55577 4.24032 4.6084 4.10783 4.6084C3.97533 4.6084 3.84826 4.55577 3.75456 4.4621L2.34148 3.04802C2.29375 3.00192 2.25569 2.94679 2.2295 2.88583C2.20331 2.82486 2.18953 2.7593 2.18895 2.69295C2.18837 2.6266 2.20102 2.56081 2.22614 2.4994C2.25127 2.43799 2.28837 2.3822 2.33528 2.33528C2.3822 2.28837 2.43799 2.25127 2.4994 2.22614C2.56081 2.20102 2.6266 2.18837 2.69295 2.18895C2.7593 2.18953 2.82486 2.20331 2.88583 2.2295C2.94679 2.25569 3.00192 2.29375 3.04802 2.34148L4.4611 3.75456C4.50763 3.80097 4.54455 3.85611 4.56974 3.91682C4.59493 3.97752 4.6079 4.0426 4.6079 4.10833C4.6079 4.17405 4.59493 4.23913 4.56974 4.29984C4.54455 4.36054 4.50763 4.41568 4.4611 4.4621Z" fill="#F1F2F4"/>
      </svg>
    `;

    function updateIcon(isDark) {
      toggleBtn.innerHTML = isDark ? sunSvg : moonSvg;
    }

    if (isDarkTheme) {
      updateIcon(true);
    }

    // [보완] 클릭 리스너의 범위를 body 대신 document로 넓게 유지하되, 버블링 최적화
    document.addEventListener('click', (event) => {
      const themeToggleBtn = event.target.closest('button[aria-label="다크 모드 전환"]');
      if (!themeToggleBtn) return;

      document.body.classList.toggle('dark-mode');

      const isDarkMode = document.body.classList.contains('dark-mode');
      if (isDarkMode) {
        setState({ theme: THEME.DARK });
        updateIcon(true);
      } else {
        setState({ theme: THEME.LIGHT });
        updateIcon(false);
      }
    });
  }

  /* -------------------------------------------------- */
  /* [파트 2] 환영 아이콘 로테이션                        */
  /* -------------------------------------------------- */
  const iconContainer = document.querySelector('.title-area .no-wrap-group');
  if (iconContainer) {
    const icon0_default = iconContainer.innerHTML;
    const icon1_rocket = `
      <svg xmlns="http://www.w3.org/2000/svg" width="30" height="30" fill="currentColor" class="bi bi-rocket-takeoff" viewBox="0 0 16 16">
        <path d="M9.752 6.193c.599.6 1.73.437 2.528-.362s.96-1.932.362-2.531c-.599-.6-1.73-.438-2.528.361-.798.8-.96 1.933-.362 2.532"/>
        <path d="M15.811 3.312c-.363 1.534-1.334 3.626-3.64 6.218l-.24 2.408a2.56 2.56 0 0 1-.732 1.526L8.817 15.85a.51.51 0 0 1-.867-.434l.27-1.899c.04-.28-.013-.593-.131-.956a9 9 0 0 0-.249-.657l-.082-.202c-.815-.197-1.578-.662-2.191-1.277-.614-.615-1.079-1.379-1.275-2.195l-.203-.083a10 10 0 0 0-.655-.248c-.363-.119-.675-.172-.955-.132l-1.896.27A.51.51 0 0 1 .15 7.17l2.382-2.386c.41-.41.947-.67 1.524-.734h.006l2.4-.238C9.005 1.55 11.087.582 12.623.208c.89-.217 1.59-.232 2.08-.188.244.023.435.06.57.093q.1.026.16.045c.184.06.279.13.351.295l.029.073a3.5 3.5 0 0 1 .157.721c.055.485.051 1.178-.159 2.065m-4.828 7.475.04-.04-.107 1.081a1.54 1.54 0 0 1-.44.913l-1.298 1.3.054-.38c.072-.506-.034-.993-.172-1.418a9 9 0 0 0-.164-.45c.738-.065 1.462-.38 2.087-1.006M5.205 5c-.625.626-.94 1.351-1.004 2.09a9 9 0 0 0-.45-.164c-.424-.138-.91-.244-1.416-.172l-.38.054 1.3-1.3c.245-.246.566-.401.91-.44l1.08-.107zm9.406-3.961c-.38-.034-.967-.027-1.746.163-1.558.38-3.917 1.496-6.937 4.521-.62.62-.799 1.34-.687 2.051.107.676.483 1.362 1.048 1.928.564.565 1.25.941 1.924 1.049.71.112 1.429-.067 2.048-.688 3.079-3.083 4.192-5.444 4.556-6.987.183-.771.18-1.345.138-1.713a3 3 0 0 0-.045-.283 3 3 0 0 0-.3-.041Z"/>
        <path d="M7.009 12.139a7.6 7.6 0 0 1-1.804-1.352A7.6 7.6 0 0 1 3.794 8.86c-1.102.992-1.965 5.054-1.839 5.18.125.126 3.936-.896 5.054-1.902Z"/>
      </svg>
    `;

    const icon2_star = `
      <svg xmlns="http://www.w3.org/2000/svg" width="30" height="30" fill="currentColor" class="bi bi-stars" viewBox="0 0 16 16">
        <path d="M7.657 6.247c.11-.33.576-.33.686 0l.645 1.937a2.89 2.89 0 0 0 1.829 1.828l1.936.645c.33.11.33.576 0 .686l-1.937.645a2.89 2.89 0 0 0-1.828 1.829l-.645 1.936a.361.361 0 0 1-.686 0l-.645-1.937a2.89 2.89 0 0 0-1.828-1.828l-1.937-.645a.361.361 0 0 1 0-.686l1.937-.645a2.89 2.89 0 0 0 1.828-1.828zM3.794 1.148a.217.217 0 0 1 .412 0l.387 1.162c.173.518.579.924 1.097 1.097l1.162.387a.217.217 0 0 1 0 .412l-1.162.387A1.73 1.73 0 0 0 4.593 5.69l-.387 1.162a.217.217 0 0 1-.412 0L3.407 5.69A1.73 1.73 0 0 0 2.31 4.593l-1.162-.387a.217.217 0 0 1 0-.412l1.162-.387A1.73 1.73 0 0 0 3.407 2.31zM10.863.099a.145.145 0 0 1 .274 0l.258.774c.115.346.386.617.732.732l.774.258a.145.145 0 0 1 0 .274l-.774.258a1.16 1.16 0 0 0-.732.732l-.258.774a.145.145 0 0 1-.274 0l-.258-.774a1.16 1.16 0 0 0-.732-.732L9.1 2.137a.145.145 0 0 1 0-.274l.774-.258c.346-.115.617-.386.732-.732z"/>
      </svg>
    `;

    function updateWelcomeIcon(stateNum) {
      if (stateNum === 1) iconContainer.innerHTML = icon1_rocket;
      else if (stateNum === 2) iconContainer.innerHTML = icon2_star;
      else iconContainer.innerHTML = icon0_default;
    }

    const { welcomeIndex } = getState();
    const welcomeCurrentIndex = welcomeIndex ?? 0;
    const welcomeNextIndex = (welcomeCurrentIndex + 1) % 3;
    setState({ welcomeIndex: welcomeNextIndex });

    updateWelcomeIcon(welcomeCurrentIndex);
  }

  /* -------------------------------------------------- */
  /* [파트 3] 사용자 이름 상태 관리                         */
  /* -------------------------------------------------- */
  const nameDOM = document.querySelector('.title-area .click-purple');
  if (nameDOM) {
    const { nickname } = getState();
    if (nickname) nameDOM.textContent = nickname;

    // 공통 이름 저장 처리 함수
    const saveNickname = () => {
      const currentName = nameDOM.textContent.trim();
      if (currentName) {
        setState({ nickname: currentName });
      } else {
        nameDOM.textContent = 'FlowDash';
        setState({ nickname: 'FlowDash' });
      }
    };

    nameDOM.addEventListener('blur', saveNickname);

    // [보완] 엔터(Enter) 키 입력 시에도 포커스를 잃게 함으로써 자연스럽게 저장 유도
    nameDOM.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault(); // 줄바꿈 방지
        nameDOM.blur(); // blur 이벤트를 발생시켜 saveNickname()이 자동 호출되도록 함
      }
    });
  }

  /* -------------------------------------------------- */
  /*  [타이머] 로딩 시차 조율                              */
  /* -------------------------------------------------- */
  document.body.classList.add('theme-loaded');

  const boardBox = document.getElementById('board');
  if (boardBox) {
    boardBox.classList.add('board-ready');
  }

  /* -------------------------------------------------- */
  /* [파트 4] 시간대별 실시간 인사말 반영 로직              */
  /* -------------------------------------------------- */
  function getGreetingByTime() {
    const currentHour = new Date().getHours();
    if (currentHour >= 6 && currentHour < 12) return '좋은 아침입니다,';
    if (currentHour >= 12 && currentHour < 14) return '좋은 점심입니다,';
    if (currentHour >= 14 && currentHour < 18) return '좋은 오후입니다,';
    if (currentHour >= 18 && currentHour < 22) return '좋은 저녁입니다,';
    return '좋은 밤입니다,';
  }

  const greetingDOM = document.querySelector('.greeting-text');
  if (greetingDOM) greetingDOM.textContent = getGreetingByTime();

  /* -------------------------------------------------- */
  /* [파트 5] 오늘 날짜 실시간 반영 로직                     */
  /* -------------------------------------------------- */
  const dateDOM = document.querySelector('.current-date');
  if (dateDOM) {
    const today = new Date();
    const year = today.getFullYear();
    const month = today.getMonth() + 1;
    const date = today.getDate();

    dateDOM.textContent = `${year}년 ${month}월 ${date}일`;

    const formattedMonth = String(month).padStart(2, '0');
    const formattedDate = String(date).padStart(2, '0');
    dateDOM.setAttribute('datetime', `${year}-${formattedMonth}-${formattedDate}`);
  }
}
